import json
def transform(g):
    H,W=len(g),len(g[0]); out=[r[:] for r in g]
    fives=[(r,c) for r in range(H) for c in range(W) if g[r][c]==5]
    # find vertical 5-line and horizontal 5-line
    cols={}; rows={}
    for r,c in fives: cols.setdefault(c,[]).append(r); rows.setdefault(r,[]).append(c)
    vcol=max(cols,key=lambda c:len(cols[c])) if cols else None
    hrow=max(rows,key=lambda r:len(rows[r])) if rows else None
    # demo-like: vertical line + horizontal pattern strip at one end
    # general approach: for each maximal colored block adjacent to a 5-line, tile it into rectangle
    # find colored blocks (nonzero, non-5) 4-connected
    seen=set(); blocks=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] not in (0,5) and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); b=[]
                while st:
                    a,bc=st.pop(); b.append((a,bc))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=a+dr,bc+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc] not in (0,5) and (nr,nc) not in seen:
                            seen.add((nr,nc)); st.append((nr,nc))
                blocks.append(b)
    for b in blocks:
        rs=[x[0] for x in b]; cs=[x[1] for x in b]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        ph,pw=r1-r0+1,c1-c0+1
        pat=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        # adjacent 5-line: vertical line next to block (left/right) or horizontal (above/below)
        if vcol is not None and (c0-1==vcol or c1+1==vcol) and any((rr,vcol) in set(fives) for rr in range(r0,r1+1)):
            vr=sorted(cols[vcol]); span=range(min(min(vr),r0),max(max(vr),r1)+1)
            cc0 = c0 if c0-1==vcol else c1+1
            crange=range(cc0, cc0+pw)
            anchor=r1 if (r1+1 in vr or r0-1 not in vr) else r0
            # anchor row = row where block touches the line end (corner); tile aligned so pattern at anchor matches
            for rr in span:
                for cc in crange:
                    out[rr][cc]=pat[(rr-r0)%ph][(cc-c0) if False else 0] if pw==1 else pat[(rr-r0)%ph][cc-c0]
        elif hrow is not None and (r0-1==hrow or r1+1==hrow) and any((hrow,cc) in set(fives) for cc in range(c0,c1+1)):
            hr=sorted(rows[hrow]); span=range(min(min(hr),c0),max(max(hr),c1)+1)
            rr0 = r0 if r0-1==hrow else r1+1
            rrange=range(rr0, rr0+ph)
            for rr in rrange:
                for cc in span:
                    out[rr][cc]=pat[rr-r0][(cc-c0)%pw]
    return out
